INCLUDE PERFETTO MODULE slices.with_context;
WITH h AS (SELECT * FROM slice WHERE name IN ('GFSDP::post_backward_reduce (mtp.layers.0)','GFSDP::post_backward_reduce (layers.0)','GFSDP::post_backward_reduce (tok_embeddings)','GFSDP::all_gather (tok_embeddings)')), l AS (SELECT h.id hid,d.id lid FROM h JOIN descendant_slice(h.id) d WHERE d.category IN ('cuda_runtime','cuda_driver')), k AS (SELECT l.hid,g.* FROM l JOIN flow f ON f.slice_out=l.lid JOIN slice g ON g.id=f.slice_in WHERE g.category='kernel')
SELECT h.id host_id,h.name scope,h.ts host_ts,h.dur host_dur,k.id kernel_id,k.name,k.ts,k.dur,EXTRACT_ARG(k.arg_set_id,'args.stream') stream FROM h JOIN k ON k.hid=h.id ORDER BY k.ts;

