SELECT h.id host_id,h.name scope,k.id kernel_id,k.name,k.ts,k.dur,EXTRACT_ARG(k.arg_set_id,'args.stream') stream,EXTRACT_ARG(k.arg_set_id,'args.In msg nelems') input_elements,EXTRACT_ARG(k.arg_set_id,'args.Out msg nelems') output_elements,EXTRACT_ARG(k.arg_set_id,'args.dtype') dtype,EXTRACT_ARG(k.arg_set_id,'args.Group size') group_size,COALESCE((SELECT SUM(MAX(0,MIN(k.ts+k.dur,z.ts+z.dur)-MAX(k.ts,z.ts))) FROM slice z WHERE z.category='kernel' AND EXTRACT_ARG(z.arg_set_id,'args.stream')=7 AND z.ts<k.ts+k.dur AND z.ts+z.dur>k.ts),0)/1e6 main_overlap_ms,(SELECT MAX(z.ts+z.dur) FROM slice z WHERE z.category='kernel' AND EXTRACT_ARG(z.arg_set_id,'args.stream')=7 AND z.ts<k.ts+k.dur AND z.ts+z.dur>k.ts) last_main_end_ts FROM h JOIN k ON k.hid=h.id ORDER BY k.ts;

